import torch

from .recurrent_decode import gated_delta_rule_decode


def fused_sigmoid_gating_delta_rule_update(
    A_log: torch.Tensor,
    a: torch.Tensor,
    b: torch.Tensor,
    dt_bias: torch.Tensor,
    q: torch.Tensor,
    k: torch.Tensor,
    v: torch.Tensor,
    beta: float = 1.0,
    threshold: float = 20.0,
    scale: float = None,
    initial_state: torch.Tensor = None,
    inplace_final_state: bool = True,
    cu_seqlens: torch.Tensor | None = None,
    ssm_state_indices: torch.Tensor | None = None,
    num_accepted_tokens: torch.Tensor | None = None,
    use_qk_l2norm_in_kernel: bool = False,
    is_kda: bool = False,
):
    """Fused sigmoid gating and delta-rule update used during verification.

    Shares :func:`gated_delta_rule_decode` with the non-speculative decode fast
    path, so both advance the recurrent state with the same kernel and tile
    configuration.
    """
    B, T, H, K, V = *k.shape, v.shape[-1]
    HV = v.shape[2]
    N = B if cu_seqlens is None else len(cu_seqlens) - 1

    if cu_seqlens is not None and q.shape[0] != 1:
        raise ValueError(
            f"The batch size is expected to be 1 rather than {q.shape[0]}"
            f" when using `cu_seqlens`. Please flatten variable-length"
            f" inputs before processing."
        )
    if scale is None:
        scale = K**-0.5
    else:
        assert scale > 0, "scale must be positive"

    q, k, v = q.contiguous(), k.contiguous(), v.contiguous()
    a, b = a.contiguous(), b.contiguous()

    o = q.new_empty(1, *v.shape)
    if inplace_final_state:
        final_state = initial_state
    else:
        final_state = q.new_empty(T, HV, V, K, dtype=initial_state.dtype)

    gated_delta_rule_decode(
        A_log=A_log,
        a=a,
        b=b,
        dt_bias=dt_bias,
        q=q,
        k=k,
        v=v,
        o=o,
        initial_state=initial_state,
        final_state=final_state,
        scale=scale,
        num_seqs=N,
        num_tokens=T,
        H=H,
        HV=HV,
        K=K,
        V=V,
        beta=beta,
        threshold=threshold,
        cu_seqlens=cu_seqlens,
        ssm_state_indices=ssm_state_indices,
        num_accepted_tokens=num_accepted_tokens,
        use_qk_l2norm_in_kernel=use_qk_l2norm_in_kernel,
        is_kda=is_kda,
        inplace_final_state=inplace_final_state,
    )
    return o.squeeze(0), final_state
